Adicione essa função antes do `return (...)` (ou dentro do módulo, onde fizer sentido):

```jsx
const archivePurchase = async (id) => {
  try {
    // Supondo que o endpoint seja POST /compras/:id/archive
    await api.post(`/compras/${id}/archive`);

    // Atualiza o status localmente para "Arquivada"
    updateTrackingStatus(id, "Compra arquivada");
    setPurchases(prev => prev.filter(p => p._id !== id));
    setRefresh(!refresh);
